function txt(chars, size, style, color, name) {
  const t = figma.createText();
  t.fontName = {family:'Inter', style: style||'Regular'};
  t.fontSize = size; t.characters = chars;
  t.fills = solid(color||C.ink);
  if (name) t.name = name;
  return t;
}
function frame(name, w, h, fill) {
  const f = figma.createFrame();
  f.name = name; f.resize(w, h);
  f.fills = fill ? solid(fill) : [];
  f.clipsContent = false;
  return f;
}
function iconInst(id, name, size, color) {
  const comp = figma.getNodeById(id);
  const i = comp.createInstance();
  i.name = name;
  if (size && size !== 24) i.resize(size, size);
  if (color) {
    const paint = solid(color);
    const walk = n => {
      if ('strokes' in n && n.strokes && n.strokes.length) n.strokes = paint;
      if ('fills' in n && n.fills && n.fills.length && n.fills.some(f=>f.visible)) n.fills = paint;
      if ('children' in n) n.children.forEach(walk);
    };
    walk(i);
  }
  return i;
}

