  sb.name='Status Bar'; sb.x=0; sb.y=0; f.appendChild(sb);
  if (dark){ const p=solid(C.white); const walk=n=>{if('fills' in n&&n.fills&&n.fills.length&&n.fills.some(x=>x.visible))n.fills=p;if('strokes' in n&&n.strokes&&n.strokes.length)n.strokes=p;if('children' in n)n.children.forEach(walk);}; walk(sb); }
  const hi = figma.getNodeById('1:44').createInstance();
  hi.name='Home Indicator'; hi.x=0; hi.y=862; f.appendChild(hi);
  if (dark){ hi.children.forEach(n=>{ if(n.type==='RECTANGLE') n.fills=solid(C.white); }); }
}
// place an icon over an instance whose default icon is hidden
function overlayIcon(f, iconId, ix, iy, size, color, name){
  const ic = iconInst(iconId, name||'Icon', size, color);
  ic.x=ix; ic.y=iy; f.appendChild(ic); return ic;
}

