  hint.x=32; hint.y=140; hint.resize(350,18); hint.textAlignHorizontal='CENTER'; f.appendChild(hint);
  // PIN dots: 4 positions, 3 entered (9,7,7), 4th empty
  const digits = ['9','7','7',''];
  digits.forEach((d,i)=>{
    const dot = figma.getNodeById('7:72').createInstance();
    dot.name = d ? 'PIN Dot '+d : 'PIN Dot Empty';
    dot.x = 67 + i*80; dot.y = 200; f.appendChild(dot);
    const dt = dot.findOne(n=>n.name==='Digit');
    dt.characters = d;
    if (!d) {
      // empty state: show ring only
      dt.visible = false;
      const ring = figma.createEllipse();
      ring.resize(64,64); ring.x=67+i*80; ring.y=200;
      ring.fills=[]; ring.strokes=solid(C.line); ring.strokeWeight=2;
      ring.name='PIN Ring Empty'; f.appendChild(ring);
    }
  });
  // Keypad 1-9, 0 with letters + delete
  const keys = [
