  const o = {id:n.id, name:n.name, type:n.type, x:Math.round(n.x), y:Math.round(n.y), w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type==='TEXT') o.chars = n.characters;
  try { if ('fills' in n && n.fills!==figma.mixed && n.fills.length && n.fills[0].type==='SOLID') { const c=n.fills[0].color; o.fill='#'+[c.r,c.g,c.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join(''); } } catch(e){}
  if ('children' in n && depth>0) o.children = n.children.map(c=>dump(c,depth-1));
  return o;
}
