function tabInfo(f) {
  const tb = f.children.find(c=>c.name==='Tab Bar');
  if (!tb) return null;
  return tb.children.map(ch=>{
    const lbl = ch.findOne(n=>n.type==='TEXT');
    const ic = ch.findOne(n=>n.name==='Icon');
    const vec = ic ? ic.findOne(n=>n.type==='VECTOR'||n.type==='GROUP') : null;
    let fillHex = null;
    try { const src = vec && 'fills' in vec && vec.fills!==figma.mixed && vec.fills[0] ? vec.fills[0] : (ic && ic.fills!==figma.mixed && ic.fills[0] ? ic.fills[0] : null); if (src && src.type==='SOLID') fillHex='#'+[src.color.r,src.color.g,src.color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join(''); } catch(e){}
    const dot = ch.findOne(n=>n.name==='Active Dot');
    return {tab:ch.name, label:lbl?lbl.characters:null, labelFill: lbl&&lbl.fills[0]&&lbl.fills[0].color ? '#'+[lbl.fills[0].color.r,lbl.fills[0].color.g,lbl.fills[0].color.b].map(v=>Math.round(v*255).toString(16).padStart(2,'0')).join('') : null, iconVisible: ic?ic.visible:null, iconFill: fillHex, dotVisible: dot?dot.visible:null};
  });
}
