// Icon button wrapper: hides default icon, overlays correct one
function iconBtn(parent,iconId,x,y){
  const wrap=figma.createFrame();
  wrap.name='IconBtn';
  wrap.resize(40,40);
  wrap.x=x; wrap.y=y;
  wrap.fills=[];
  wrap.clipsContent=false;
  parent.appendChild(wrap);
  const btn=figma.getNodeById('7:2').createInstance();
  btn.x=0; btn.y=0;
  wrap.appendChild(btn);
  const inner=btn.findOne(n=>n.name==='Icon');
  if(inner) inner.visible=false;
  const icon=figma.getNodeById(iconId).createInstance();
  icon.x=8; icon.y=8;
  wrap.appendChild(icon);
  return wrap;
}

// Activate Invest tab in a Tab Bar instance
function activateInvest(tb){
  const tabs=['Tab Main','Tab Payments','Tab Cashback','Tab Invest','Tab More'];
  tabs.forEach(name=>{
    const tab=tb.findOne(n=>n.name===name);
    if(!tab)return;
    const isActive=name==='Tab Invest';
    const col=isActive?BRAND:MID;
    tab.findAll(n=>n.type==='VECTOR').forEach(v=>{try{v.fills=solid(col);}catch(e){}});
    const lbl=tab.findOne(n=>n.name==='Label');
    if(lbl){try{lbl.fills=solid(col);}catch(e){}}
    const dot=tab.findOne(n=>n.name==='Active Dot');
    if(dot) dot.visible=isActive;
  });
}

