const log=[];

function fixFrame(fid){
  const f=figma.getNodeById(fid);
  // 1. Buy button label
  const btn=f.children.find(c=>c.name==='Button');
  if(btn){
    const t=btn.findOne(n=>n.type==='TEXT');
    if(t && t.characters!=='Buy'){ t.characters='Buy'; log.push(fid+' btn->Buy'); }
  }
  // 2. Text fields values
  const fields=f.children.filter(c=>c.name==='Text Field');
  fields.forEach(tf=>{
    const input=tf.findOne(n=>n.name==='Input');
    if(input){
      const vt=input.findOne(n=>n.type==='TEXT');
      const lbl=tf.findOne(n=>n.name==='Quantity');
      if(vt){
        if(lbl && lbl.characters==='Quantity' && vt.characters!=='1'){ vt.characters='1'; vt.fills=solid(DARK); log.push(fid+' qty=1'); }
        if(lbl && lbl.characters==='Price' && vt.characters==='$0.00'){ vt.characters='$143.43'; vt.fills=solid(DARK); log.push(fid+' price set'); }
      }
    }
  });
  // 3. Account card selected state: USD gets brand stroke + check badge
  const cards=f.children.filter(c=>c.name==='Account Card');
  if(cards.length===2){
    const usd=cards[0], eur=cards[1];
    usd.strokes=solid(BRAND);
    usd.strokeWeight=2;
    eur.strokes=solid({r:0.9,g:0.9,b:0.92});
    eur.strokeWeight=1;
    // check badge on USD (only if not already added)
    if(!f.children.find(c=>c.name==='USD Check')){
      const badge=figma.createEllipse();
      badge.name='USD Check';
      badge.resize(20,20);
      badge.fills=solid(BRAND);
      badge.x=usd.x+usd.width-30;
      badge.y=usd.y+10;
      f.appendChild(badge);
      // checkmark vector via simple lines
      const l1=figma.createRectangle();
      l1.name='USD Checkmark A';
      l1.resize(7,2); l1.fills=solid(WHITE);
      l1.rotation=-45;
      l1.x=badge.x+4; l1.y=badge.y+11;
      f.appendChild(l1);
      const l2=figma.createRectangle();
      l2.name='USD Checkmark B';
      l2.resize(11,2); l2.fills=solid(WHITE);
      l2.rotation=45;
      l2.x=badge.x+7; l2.y=badge.y+7;
      f.appendChild(l2);
      log.push(fid+' usd selected');
    }
  }
}

