function dump(n, depth) {
  const o = {n:n.name, t:n.type[0], x:Math.round(n.x), y:Math.round(n.y), w:Math.round(n.width), h:Math.round(n.height)};
  if (n.type==='TEXT') o.c=n.characters;
  if ('children' in n && depth>0) o.k=n.children.map(c=>dump(c,depth-1));
  return o;
}
