  const icons = f.findAll(n=>n.type==='INSTANCE' && /^Icon_/.test(n.name)).map(n=>n.name);
  out[nm]={id:f.id, reacts, iconCount:icons.length, icons:[...new Set(icons)]};
});
return JSON.stringify(out,null,1);

